local WelfareTabToggleLeftCell = Class("WelfareTabToggleLeftCell", CommonTabToggleLeftCell)
local WelfareConstants = import("Game.UI.Welfare.WelfareConstants")
--region lifecycle
---@override
function WelfareTabToggleLeftCell:Awake()
    self.super.Awake(self)
    self:PlayAnimation()
end

---@override
function WelfareTabToggleLeftCell:FreshSelectStatus(isSelected)
    KTool.SetActive(self.Image, isSelected)
    CfUtils.SetUISwitchText(self.Text.transform, isSelected and SwitchTextStatusEnum.SELECTED or SwitchTextStatusEnum.DEFAULT)


    if isSelected then
        CfUtils.SetColor(self.ImgIcon, XLuaUtils.HexToColor("#666666"))
        CfUtils.SetScale(self.ImgIcon, Vector3(0.5, 0.5, 1))
        --self.redPoint.transform.anchoredPosition = Vector3(50, 15, 0)
    else
        CfUtils.SetColor(self.ImgIcon, XLuaUtils.HexToColor("#a3a3a3"))
        CfUtils.SetScale(self.ImgIcon, Vector3(0.4, 0.4, 1))
        --self.redPoint.transform.anchoredPosition = Vector3(46, 15, 0)
    end
end
--endregion lifecycle

--region inheritance
---@override
function WelfareTabToggleLeftCell:FreshBaseUI(data)
    ---@type WelfareDojo
    local dojo = data.dojo
    self.Text.text = data.dojo.name
    KTool.SetActive(self.TextDay, dojo.endTime ~= nil)
    if dojo.endTime ~= nil then
        self.TextDay.text = ActivityUtils.ConventLeftTimeText(dojo.endTime)
    end
    if dojo.redNode ~= nil then
        GameUtils.BindRedPoint(dojo.redNode, self.TextTitle, true)
    else
        KTool.SetActive(self.redPoint, checkInt(dojo.redDotHint) == 0)
    end
    if dojo.welfareId == WelfareConstants.OpenIds.MonthlyMembership then
        local leftTime = StoreUtils.GetMonthlyCardLeftTime()
        self:RefreshMonthCardTab(leftTime)
    elseif data.dojo.welfareId == WelfareConstants.OpenIds.CardMonthMembership then
        ---@type PlayerComponent
        local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
        local leftTime = component:GetPrivilegeCardSecondsById(dojo.monthCardId)
        self:RefreshMonthCardTab(leftTime)
    else
        local urgency = ActivityUtils.IsUrgentTime(data.dojo.endTime)
        if urgency then
            CfUtils.SetUISwitchText(self.TextDay, TextDayStatusEnum.URGENCY)
        else
            CfUtils.SetUISwitchText(self.TextDay, data.isSelected and TextDayStatusEnum.SELECTED or TextDayStatusEnum.DEFAULT)
        end
    end

end
---刷新月卡页签
function WelfareTabToggleLeftCell:RefreshMonthCardTab(leftTime)
    if leftTime then
        local days = math.floor(leftTime / 86400)
        if days >= 7 then
            KTool.SetActive(self.TextDay, true)
            CfUtils.FillText(self.TextDay, localize("_num_天", {_num_ = days}))
        else
            KTool.SetActive(self.TextDay, false)
        end
    else
        KTool.SetActive(self.TextDay, false)
    end
end
--endregion inheritance

--region public
---刷新icon
---@param path string icon路径
function WelfareTabToggleLeftCell:FreshIcon(path)
    CfUtils.FillImage(self.ImgIcon.gameObject, path)
    CfUtils.FillImage(self.ImgIconShadow.gameObject, path)
end
---播放选中动画
function WelfareTabToggleLeftCell:PlayAnimation()
    CfUtils.PlayAnimator(self.AnimRoot, "Go")
end
